ALTER TABLE app.mission_market DROP CONSTRAINT mission_market_country_code_check;
CREATE FUNCTION app.valid_legacy_country(c text) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT c='OTHER' OR EXISTS(SELECT FROM app.country WHERE code=c) $$;
REVOKE ALL ON FUNCTION app.valid_legacy_country(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.valid_legacy_country(text) TO corridra_runtime;
ALTER TABLE app.mission_market ADD CHECK(country_code IS NULL OR app.valid_legacy_country(country_code));
ALTER TABLE app.communication_policy DROP CONSTRAINT communication_policy_jurisdiction_check;
ALTER TABLE app.communication_policy ADD CHECK(app.valid_legacy_country(jurisdiction));
CREATE OR REPLACE FUNCTION app.ingest_public_organisation(target uuid,sid uuid,company text,cc text,host text,addr text,itype text,ident text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE src record; oid uuid:=gen_random_uuid();
BEGIN
 IF app.member_role(target) IS NULL OR app.member_role(target) NOT IN ('owner','admin','operator') OR NOT EXISTS(SELECT FROM app.tenant WHERE id=target AND synthetic) THEN RAISE EXCEPTION 'Synthetic operator required' USING ERRCODE='42501'; END IF;
 SELECT * INTO src FROM app.source_record WHERE tenant_id=target AND id=sid AND classification='PUBLIC' AND kind='public_record' AND app.can_access(target,classification,purpose) AND retention_until>now() AND observed_at<=now() AND ai_policy='DENY';
 IF NOT FOUND OR src.locator !~ '^https://([a-z0-9-]+\.)*example\.invalid(/[^[:space:]]*)?$' OR length(company) NOT BETWEEN 1 AND 160 OR (cc IS NULL OR NOT EXISTS(SELECT FROM app.country WHERE code=cc)) THEN RAISE EXCEPTION 'Current synthetic public-record source required'; END IF;
 INSERT INTO app.organisation(id,name,country,synthetic) VALUES(oid,company,cc,true);
 INSERT INTO app.public_identifier(organisation_id,identifier_type,identifier,domain,address,source_locator,observed_at,valid_until,synthetic) VALUES(oid,itype,ident,host,addr,src.locator,src.observed_at,src.retention_until,true);
 INSERT INTO app.organisation_source(tenant_id,organisation_id,source_id,purpose,created_by) VALUES(target,oid,sid,src.purpose,app.actor_id());
 RETURN oid;
END $$;
-- Preserve historic unclassified values; enforce canonical identifiers on future writes.
ALTER TABLE app.organisation ADD CONSTRAINT organisation_country_registry FOREIGN KEY(country) REFERENCES app.country(code) NOT VALID;
